import difflib, subprocess, sys, re, collections
root = '/home/user/fortress-libslips'
base = '7fa767d48'
def mapping(path):
    old = subprocess.run(['git','-C',root,'show',f'{base}:{path}'],capture_output=True,text=True).stdout.splitlines()
    new = open(f'{root}/{path}').read().splitlines()
    m = {}
    for tag,i1,i2,j1,j2 in difflib.SequenceMatcher(None, old, new, autojunk=False).get_opcodes():
        for k in range(j2-j1):
            if tag == 'equal' or (tag == 'replace' and k < i2-i1):
                m[j1+k+1] = (i1+k+1, tag)
            else:
                m[j1+k+1] = (i1, 'insert-after')
    return m
maps = {'FortressLibrary.fss': mapping('Library/FortressLibrary.fss'), 'FortressLibrary.fsi': mapping('Library/FortressLibrary.fsi')}
def remap(loc):
    out = []
    for part in loc.split(','):
        mm = re.match(r'(FortressLibrary\.fs[si]):(\d+)$', part)
        if mm and mm.group(1) in maps:
            n, tag = maps[mm.group(1)][int(mm.group(2))]
            out.append(f'{mm.group(1)}:{n}' + ('' if tag=='equal' else f'[{tag}]'))
        else:
            out.append(part)
    return ','.join(out)
def rows(path, do_map):
    c = collections.Counter()
    for line in open(path):
        if line.startswith('#') or not line.strip(): continue
        f = line.rstrip('\n').split('\t')
        loc = remap(f[5]) if do_map else f[5]
        key = (f[3], re.sub(r'\[(equal|replace|insert-after)\]','',loc), f[6])
        c[key] += 1
    return c
landed = rows(f'{root}/explorations/compile-ladder/gate/distance-sites.tsv', False)
post = rows(f'{root}/tmp/rung-library-slips/dist-post/errors.tsv', True)
gone = landed - post
new = post - landed
print('landed', sum(landed.values()), 'post', sum(post.values()))
print('GONE', sum(gone.values()))
for k,v in sorted(gone.items(), key=lambda kv: int(re.search(r':(\d+)',kv[0][1]).group(1)) if re.search(r':(\d+)',kv[0][1]) else 0):
    print(f'  -{v}\t{k[0]}\t{k[1]}\t{k[2][:150]}')
print('NEW', sum(new.values()))
for k,v in new.items():
    print(f'  +{v}\t{k[0]}\t{k[1]}\t{k[2][:220]}')
EOF
